function parseCSV(text) {
  if (!text) return [];
  const lines = text.trim().split('\n');
  if (lines.length < 2) return [];
  const headers = lines[0].split(',').map(h => h.trim().replace(/^"|"$/g, ''));
  return lines.slice(1).map(line => {
    const fields = [];
    let cur = '', inQ = false;
    for (let i = 0; i < line.length; i++) {
      if (line[i] === '"') { inQ = !inQ; }
      else if (line[i] === ',' && !inQ) { fields.push(cur.trim()); cur = ''; }
      else { cur += line[i]; }
    }
    fields.push(cur.trim());
    const obj = {};
    headers.forEach((h, i) => { obj[h] = (fields[i] || '').replace(/^"|"$/g, '').trim(); });
    return obj;
  }).filter(r => Object.values(r).some(v => v !== ''));
}

const allItems = $input.all();
const menuCSV = allItems[0]?.json?.data || '';
const allergenesCSV = allItems[1]?.json?.data || '';
const offresCSV = allItems[2]?.json?.data || '';

const menu = parseCSV(menuCSV);
const allergens = parseCSV(allergenesCSV);
const offres = parseCSV(offresCSV);

const today = new Date().toLocaleDateString('fr-CH',{day:'2-digit',month:'2-digit',year:'numeric'}).replace(/\//g,'.');

let menuText = `## MENU DU JOUR (${today})\n`;
const cats = ['PLAT','RIZ','ENTREE','ENTRÉE','NAAN','DESSERT','BOISSON'];
for (const cat of cats) {
  const items = menu.filter(i => i.catégorie?.toUpperCase().replace('É','E') === cat.replace('É','E') && i.disponible?.toUpperCase() === 'OUI');
  if (!items.length) continue;
  menuText += `\n### ${cat}\n`;
  for (const d of items) {
    const tags = [];
    if (d.sans_gluten?.toUpperCase() === 'OUI') tags.push('SANS GLUTEN');
    if (Object.entries(d).find(([k,v]) => k.includes('t') && k.includes('arien') && v?.toUpperCase()==='OUI')) tags.push('VÉGÉTARIEN');
    if (d.halal?.toUpperCase() === 'OUI') tags.push('HALAL');
    menuText += `- **${d.plat}**: ${d.description}${tags.length?' ['+tags.join(' | ')+']':''}\n`;
    if (d.notes_chef) menuText += `  ↳ ${d.notes_chef}\n`;
  }
}
if (!menu.length) menuText += 'Menu non encore mis à jour — référer aux plats habituels.\n';

let allerText = '\n## ALLERGÈNES — RÈGLE ABSOLUE: ne jamais proposer un produit contenant l\'allergène mentionné\n\n';
for (const a of allergens) {
  const produit = a.produit || a.Produit || '';
  if (!produit) continue;
  const al = [];
  if (a.gluten==='✓') al.push('GLUTEN');
  if (a.lait==='✓') al.push('LAIT');
  if (a.oeufs==='✓') al.push('OEUFS');
  const fk = Object.keys(a).find(k=>k.includes('coque')||k.includes('noix'));
  if (fk && a[fk]==='✓') al.push('FRUITS À COQUE');
  const sk = Object.keys(a).find(k=>k.includes('same')||k.includes('sésame'));
  if (sk && a[sk]==='✓') al.push('SÉSAME');
  const comp = [];
  const vk = Object.keys(a).find(k=>k.includes('tarien'));
  if (vk && a[vk]==='✓') comp.push('végétarien');
  if (a.vegan==='✓') comp.push('vegan');
  if (a.halal==='✓') comp.push('halal');
  if (a.sans_gluten==='✓') comp.push('sans gluten');
  allerText += `- **${produit}**: ${al.length?'⚠️ Contient: '+al.join(', '):'✅ Sans allergène majeur'}${comp.length?' | OK: '+comp.join(', '):''}\n`;
}

let offresText = '\n## OFFRES ACTIVES\n';
const actives = offres.filter(o => { const k=Object.keys(o).find(k=>k.includes('active')); return k && o[k]?.toUpperCase()==='OUI'; });
if (!actives.length) { offresText += 'Aucune offre active.\n'; }
else { for (const o of actives) { offresText += `- **${o.code||''}**: ${o.description||''} | Condition: ${o.condition_déclenchement||o.condition||''} | Valeur: ${o.valeur_réduction||o.valeur||''}\n`; } }

const dynamicContext = '━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n# DONNÉES TEMPS RÉEL\n' + menuText + allerText + offresText + '━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━';

return [{ json: { dynamicContext } }];
